r","match":"iBiology Lectures: Development & Stem Cells — investigadores de referência sobre células estaminais e regeneração."},{"code":"14241156","playlist_id":"PLRxLNUL6CtpVSKYLpkJCNqRnPTcLfQBgE","ord":1,"confidence":"média","level":"introdutório/divulgação","match":"'ABC Epigenética' do Centro de Estudos do Genoma Humano (genoma USP)."},{"code":"14241156","playlist_id":"PLzF6mGL_E5nF_nU4XvamExnlLcUbDQFPG","ord":2,"confidence":"baixa","level":"superior","match":"Aulas de Genética e Epigenética (imprinting, herança multifatorial, DNA e ambiente)."},{"code":"14241154","playlist_id":"PLREa-1X0x4IkTtYo6fjhgDtEoLCFt5srU","ord":1,"confidence":"média","level":"superior","match":"Farmacocinética e farmacodinâmica: agonistas, antagonistas, eficácia, potência, recetores (Profa. Tatiana Lavich)."},{"code":"14241154","playlist_id":"PLokE6izDq5XNWBx8giKXq938dmHRaCPRU","ord":2,"confidence":"média","level":"superior","match":"Farmacologia médica: farmacocinética, farmacodinâmica, classes de fármacos (Teoria da Medicina)."},{"code":"14241066","playlist_id":"PLVSek57SJFtTdzGvBpmj5qvnqZ-3LL76u","ord":1,"confidence":"alta","level":"superior","match":"Algoritmos de alinhamento de sequências — projeto OnlineBioinfo (Profa. Raquel Minardi, DCC-UFMG)."},{"code":"14241066","playlist_id":"PLtMO804-tewnwai81KjcY1D8531rC43jr","ord":2,"confidence":"alta","level":"superior","match":"XIV Curso de Verão em Bioinformática da USP (2023)."},{"code":"14241155","playlist_id":"PLsPIneJCpRR74cYVdG7pJBJ927VsWU0ff","ord":1,"confidence":"média","level":"superior","match":"Sistema tegumentar: pele (epiderme, derme) e anexos (Prof. Rogério Gozzi)."},{"code":"14241155","playlist_id":"PLbKSbFnKYVY1-S3v7AumitreE3WDxDgYs","ord":2,"confidence":"alta","level":"superior","match":"Khan Academy Medicine — Integumentary system (pele, termorregulação, anexos)."}]
$fpl$::jsonb) AS x(code text,playlist_id text,ord integer,confidence text,level text,match text);

DO $pre$ BEGIN
 IF (SELECT count(*) FROM _u)<>40 OR (SELECT count(DISTINCT code) FROM _u)<>40
 OR (SELECT sum(ects) FROM _u WHERE option_group IS NULL)<>174
 OR (SELECT count(*) FROM _u WHERE option_group='Opção I')<>3 OR (SELECT count(*) FROM _u WHERE option_group='Opção 2')<>5
 OR EXISTS(SELECT 1 FROM _u WHERE option_group IS NOT NULL AND ects<>3)
 OR (SELECT count(*) FROM _p)<>60 OR (SELECT count(*) FROM _pl)<>60
 THEN RAISE EXCEPTION 'Unexpected Ciências Biomédicas manifest counts or ECTS (expected 180 = 174 + 3 + 3)'; END IF;
 IF EXISTS(SELECT 1 FROM _p WHERE id !~ '^PL[A-Za-z0-9_-]{10,60}$' OR url<>'https://www.youtube.com/playlist?list='||id
 OR length(trim(title))<3 OR videos<4 OR language NOT IN('pt-PT','pt-BR','en'))
 OR EXISTS(SELECT 1 FROM _pl t LEFT JOIN _p p ON p.id=t.playlist_id LEFT JOIN _u u ON u.code=t.code WHERE p.id IS NULL OR u.code IS NULL)
 THEN RAISE EXCEPTION 'Invalid playlist metadata or link'; END IF;
 IF EXISTS(SELECT 1 FROM facodi.courses WHERE (code='LCBM' OR slug='ciencias-biomedicas' OR (external_source='ualg_official' AND external_id='1915'))
 AND id<>md5('facodi:ualg:1915:course:record')::uuid)
 THEN RAISE EXCEPTION 'Another course already uses LCBM, ciencias-biomedicas or UAlg 1915; reconcile manually'; END IF;
 IF EXISTS(SELECT 1 FROM facodi.curricular_units cu JOIN _u u ON u.code=cu.code
 WHERE cu.course_id<>md5('facodi:ualg:1915:course:record')::uuid)
 THEN RAISE EXCEPTION 'A UC code already belongs to another course; reconcile manually'; END IF;
END $pre$;

INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,objectives,keywords,tags,language,status,published,source_type,source_url,source_id,metadata)
VALUES(md5('facodi:ualg:1915:course')::uuid,'course','Licenciatura em Ciências Biomédicas','facodi-course-ciencias-biomedicas',
 'Licenciatura da Universidade do Algarve, na Faculdade de Medicina e Ciências Biomédicas, com 180 ECTS em três anos. Biologia celular e molecular, bioquímica, genética e o estudo integrado dos sistemas do corpo humano, com microbiologia, imunologia, neurobiologia e terapias avançadas.','[]'::jsonb,ARRAY['Ciências Biomédicas','Biologia molecular','Genética','Fisiologia'],ARRAY['Ciências Biomédicas'],
 'pt','active',true,'import','https://www.ualg.pt/curso/1915','ualg:licenciatura:1915:course',
 jsonb_build_object('university_course_code','1915','official_academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1915/plano',
 'source_quality','ualg_official_programme','curation_batch','facodi_ualg_1915_ciencias_biomedicas_20261118'))
ON CONFLICT DO NOTHING;

INSERT INTO facodi.courses(id,learning_object_id,code,external_source,external_id,slug,title,normalized_title,summary,description_html,
 degree_type,language,school,source_url,plan_url,status,published,metadata,institution,ects_total,duration_semesters)
VALUES(md5('facodi:ualg:1915:course:record')::uuid,md5('facodi:ualg:1915:course')::uuid,'LCBM','ualg_official','1915','ciencias-biomedicas',
 'Licenciatura em Ciências Biomédicas','Ciências Biomédicas','Licenciatura da Universidade do Algarve, na Faculdade de Medicina e Ciências Biomédicas, com 180 ECTS em três anos. Biologia celular e molecular, bioquímica, genética e o estudo integrado dos sistemas do corpo humano, com microbiologia, imunologia, neurobiologia e terapias avançadas.','<h2>Apresentação</h2><p>A licenciatura forma profissionais que dominam os conceitos e as técnicas da ciência médica e da biologia molecular, preparados para prosseguir estudos de 2.º e 3.º ciclo ou trabalhar em biologia, biomedicina e genética médica, em laboratórios de investigação e na indústria.</p><h2>Plano de estudos</h2><p>31 unidades curriculares obrigatórias, dois grupos de opção de 3 ECTS e um projeto de 15 ECTS no último semestre. O corpo humano é estudado por sistemas orgânicos funcionais: digestivo, urinário, circulatório e respiratório, endócrino e reprodutor, nervoso, músculo-esquelético e tegumentar.</p><h2>Na FACODI</h2><p>Cada unidade curricular tem playlists abertas do YouTube escolhidas a partir do programa da ficha oficial da UC.</p>',
 'Licenciatura','pt','Faculdade de Medicina e Ciências Biomédicas','https://www.ualg.pt/curso/1915','https://www.ualg.pt/curso/1915/plano','active',true,
 jsonb_build_object('official_course_id','1915','official_academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1915/plano',
 'official_program_verified',true,'official_ects_total',180,'official_unit_count',40,'mandatory_unit_count',31,
 'curriculum_contains_elective_alternatives',true,'alternative_pathways_not_additive',true,
 'thematic_area','Ciências e Tecnologias da Saúde','teaching_language','Português',
 'source_quality','ualg_official_programme','curriculum_review_status','approved_official_plan','curation_batch','facodi_ualg_1915_ciencias_biomedicas_20261118'),
 'Universidade do Algarve',180,6)
ON CONFLICT DO NOTHING;

