INSERT INTO facodi.learning_object_relations(id,parent_object_id,child_object_id,relation_type,position,created_by_mechanism,metadata)
SELECT md5('facodi:ualg:1915:course-uc-link:'||u.code)::uuid,md5('facodi:ualg:1915:course')::uuid,md5('facodi:ualg:1915:uc:'||u.code)::uuid,
 'contains',u.position,'structured_catalog_import',
 jsonb_build_object('relation_origin','ualg_1915_official_2026_27_plan','official_code',u.code,'official_ects',u.ects,'curation_batch','facodi_ualg_1915_ciencias_biomedicas_20261118')
FROM _u u
ON CONFLICT DO NOTHING;

INSERT INTO facodi.external_sources(id,learning_object_id,source_type,external_id,source_url,title,metadata)
VALUES(md5('facodi:ualg:1915:source:course')::uuid,md5('facodi:ualg:1915:course')::uuid,'website','ualg:1915:course',
 'https://www.ualg.pt/curso/1915','Licenciatura em Ciências Biomédicas',
 jsonb_build_object('publisher','Universidade do Algarve','academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1915/plano'))
ON CONFLICT DO NOTHING;

-- Playlists: reutiliza um registo existente com o mesmo ID do YouTube; senão cria um novo.
INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,language,status,published,source_type,source_url,source_id,tags,metadata)
SELECT md5('facodi:ualg:1915:playlist:'||p.id)::uuid,'playlist',p.title,'facodi-uc-playlist-'||p.id,p.description,p.language,
 'active',true,'youtube',p.url,p.id,p.tags,
 jsonb_build_object('source_channel',p.channel,'source_channel_url',p.channel_url,'youtube_playlist_id',p.id,
 'video_count_at_verification',p.videos,'playlist_title_checked',true,'playlist_owner_verified',true,
 'owner_verification_method','youtube_oembed','items_channel_checked',true,'playlist_membership_verified',false,
 'items_automatically_imported',false,'verified_on','2026-11-18','curation_batch','facodi_ualg_1915_ciencias_biomedicas_20261118')
FROM _p p
WHERE NOT EXISTS(SELECT 1 FROM facodi.learning_objects lo WHERE lo.object_type='playlist' AND lo.source_type='youtube' AND lo.source_id=p.id)
ON CONFLICT DO NOTHING;

INSERT INTO facodi.learning_object_relations(id,parent_object_id,child_object_id,relation_type,position,created_by_mechanism,metadata)
SELECT md5('facodi:ualg:1915:uc-playlist:'||x.code||':'||x.playlist_id)::uuid,md5('facodi:ualg:1915:uc:'||x.code)::uuid,lo.id,
 'contains',91000+x.ord,'structured_catalog_import',
 jsonb_build_object('review_status','approved','review_scope','uc_programme_topic_match','match_confidence',x.confidence,
 'content_level',x.level,'match_rationale',x.match,'curation_batch','facodi_ualg_1915_ciencias_biomedicas_20261118','playlist_owner_verified',true,'members_verified',false)
FROM _pl x
JOIN LATERAL (SELECT id FROM facodi.learning_objects WHERE object_type='playlist' AND source_type='youtube' AND source_id=x.playlist_id
 ORDER BY (id=md5('facodi:ualg:1915:playlist:'||x.playlist_id)::uuid) DESC, id LIMIT 1) lo ON true
ON CONFLICT DO NOTHING;

DO $post$ DECLARE units integer; links integer; BEGIN
 SELECT count(*) INTO units FROM facodi.curricular_units
 WHERE course_id=md5('facodi:ualg:1915:course:record')::uuid AND published AND status='active' AND learning_object_id IS NOT NULL;
 SELECT count(*) INTO links FROM _pl x JOIN facodi.learning_object_relations r ON r.parent_object_id=md5('facodi:ualg:1915:uc:'||x.code)::uuid
 AND r.relation_type='contains' JOIN facodi.learning_objects lo ON lo.id=r.child_object_id AND lo.object_type='playlist' AND lo.source_id=x.playlist_id;
 IF NOT EXISTS(SELECT 1 FROM facodi.courses WHERE code='LCBM' AND published AND status='active' AND ects_total=180)
 OR units<>40 OR links<>60
 THEN RAISE EXCEPTION 'Ciências Biomédicas import not complete: units %, playlist links %',units,links; END IF;
END $post$;
